/* O brasão da escola, embutido no próprio app. É o padrão do cabeçalho de
   identificação e precisa sair sempre: o fetch('logo.png') falha quando a
   pasta é aberta direto do computador (file://) ou quando o arquivo não vem,
   e aí o cabeçalho saía sem brasão, calado. Gerado de logo.png. */
(function (global) {
    'use strict';
    const BASE64 = '';
    function bytes() {
        const bin = (typeof atob === 'function') ? atob(BASE64) : Buffer.from(BASE64, 'base64').toString('binary');
        const saida = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) saida[i] = bin.charCodeAt(i);
        return saida;
    }
    const api = { bytes: bytes, dataUrl: 'data:image/png;base64,' + BASE64 };
    global.ProvasBrasao = api;
    if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
